#!/bin/bash
# Generates trampoline_wayland.h (the wl + xkb renames) and trampoline_x11.h
# (the x11 renames) from the *_syms.h tables - the rename layer that makes
# the retargeted backends' call sites go through the dlopen'd tables.
#
# Single source of truth = the sym lists. Do NOT edit the generated blocks
# by hand; edit the list and rerun:  sh gen_trampolines.sh
# (The SDL3 precedent: SDL_waylanddyn.h carries the identical hand-written
# block; we generate ours so the table and the renames cannot drift.)

set -eu
cd "$(dirname "$0")"

# gen_block <global-suffix> <sym-file>: one #define per SYM line.
# Handles MACRO(rc, name, params) and MACRO(name) line shapes.
gen_block() {
  local suffix="$1" file="$2"
  awk -v suffix="$suffix" '
    /^[A-Z0-9_][A-Z0-9_]*\(.*\)$/ {
      line = $0
      gsub(/[), \t\r]+$/, "", line)
      n = split(line, a, /,/)
      if (n >= 3) { name = a[2] } else { name = a[1] }
      gsub(/[ \t]/, "", name)
      if (name ~ /^[A-Za-z_][A-Za-z0-9_]*$/) {
        printf "#undef %s\n", name
        printf "#define %s (*g_%s.%s)\n", name, suffix, name
      }
    }' "$file"
}

{
  echo "// GENERATED by gen_trampolines.sh from wl_syms.h + xkb_syms.h - do not edit."
  echo "// Include AFTER the type headers (wayland-client-core.h, xkbcommon.h)"
  echo "// and BEFORE wayland-client-protocol.h: the protocol inlines must see"
  echo "// the renames (they call the core API, which must hit the tables)."
  echo "#ifndef CRUX_TRAMPOLINE_WAYLAND_H"
  echo "#define CRUX_TRAMPOLINE_WAYLAND_H"
  echo '#include "wl_tables.h"'
  echo ""
  gen_block wl include/wl_syms.h
  echo ""
  gen_block xkb include/xkb_syms.h
  echo ""
  echo "#endif"
} > include/trampoline_wayland.h

{
  echo "// GENERATED by gen_trampolines.sh from x11_syms.h - do not edit."
  echo "// Include AFTER the X11 type headers (Xlib.h & co)."
  echo "#ifndef CRUX_TRAMPOLINE_X11_H"
  echo "#define CRUX_TRAMPOLINE_X11_H"
  echo '#include "x11_tables.h"'
  echo ""
  gen_block x11 include/x11_syms.h
  echo ""
  echo "#endif"
} > include/trampoline_x11.h

echo "wrote trampoline_wayland.h + trampoline_x11.h"
